//! Compiles the vendored CUI amalgamation (`c/cui.c`, `c/cui.h`) with the `cc`
//! crate. The C sources are generated by upstream `tools/amalgamate.py`; see
//! `vendor.sh` in the repository root.

fn main() {
    let mut b = cc::Build::new();
    b.file("c/cui.c");
    b.include("c");
    b.flag_if_supported("-std=c99");
    b.warnings(false);

    if !cfg!(feature = "default-fonts") {
        b.define("CUI_NO_DEFAULT_FONTS", None);
    }
    if !cfg!(feature = "stb-image") {
        b.define("CUI_NO_STB_IMAGE", None);
    }
    if !cfg!(feature = "app") {
        b.define("CUI_NO_APP", None);
    }
    if cfg!(feature = "text-shaping") {
        b.define("CUI_TEXT_SHAPING", None);
    }

    let target = std::env::var("TARGET").unwrap();
    match target.as_str() {
        // macOS: the window backend is Objective-C; the amalgamation must be
        // compiled as ObjC (upstream CI uses `-x objective-c -fobjc-arc`).
        t if t.contains("apple") => {
            b.flag("-x");
            b.flag("objective-c");
            b.flag("-fobjc-arc");
            b.define("GL_SILENCE_DEPRECATION", None);
            for fw in ["Cocoa", "QuartzCore", "OpenGL"] {
                println!("cargo:rustc-link-lib=framework={fw}");
            }
        }
        t if t.contains("windows") => {
            for lib in ["user32", "gdi32", "opengl32", "shell32", "imm32", "dwmapi", "comdlg32", "ole32"] {
                println!("cargo:rustc-link-lib=dylib={lib}");
            }
        }
        // Linux/BSD (X11 backend; SDL2/GLFW builds are not wired up here yet).
        _ => {
            println!("cargo:rustc-link-lib=dylib=X11");
            println!("cargo:rustc-link-lib=dylib=dl");
            println!("cargo:rustc-link-lib=dylib=m");
        }
    }

    b.compile("cui");

    // Expose the upstream version of the vendored sources. The version of
    // record is the CUI_VERSION_STRING define inside c/cui.h itself, so the
    // constant always describes the C code that was actually compiled.
    let header = std::fs::read_to_string("c/cui.h").expect("c/cui.h is missing; run vendor.sh");
    let version = header
        .lines()
        .find_map(|l| l.strip_prefix("#define CUI_VERSION_STRING "))
        .map(|rest| rest.trim().trim_matches('"').to_string())
        .expect("CUI_VERSION_STRING not found in c/cui.h; run vendor.sh");
    println!("cargo:rustc-env=CUI_VERSION_STRING={version}");

    println!("cargo:rerun-if-changed=c/cui.c");
    println!("cargo:rerun-if-changed=c/cui.h");
    println!("cargo:rerun-if-changed=build.rs");
}
